import React, {Component} from 'react';
import {Dimensions, Image, Text, TouchableNativeFeedback, View} from 'react-native';
import {bindActionCreators} from 'redux';
import {connect} from 'react-redux';
import styles from '../Test/TestStyles';
import NavigationBar from '../../Basic/NavigationBar';
import QAPanel from './QAPanel';
import SnapCarousel from 'react-native-snap-carousel';
import {goToQuestion, loadCarousel, loadTestAnswers, loadTestQuestions} from "../../../Redux/Playground/Test";
import axios from 'axios';
import firebaseApp from '../../Firebase.js';
import Sound from 'react-native-sound';

firebaseApp.analytics().setCurrentScreen("OngoingGym");

const sound = new Sound('http://www.slspencer.com/Sounds/Chewbacca/Chewie3.mp3', null, (error) => {
  if (error) {
    console.log("notworkinggggg" + error);
  }else{
    console.log("workingggggggggg");
  }
} );

const screen = Dimensions.get('window');

class OngoingGym extends Component<{}> {
  loadNewQuestions = () => {
    this.props.loadTestQuestions([]);
    this.props.loadTestAnswers([]);
    const {topics} = this.props.gym;
    console.log(`http://api.classcast.in/classcast/fetch/gym/?student_id=${this.props.user.id}${topics}`);
    axios.get(`http://api.classcast.in/classcast/fetch/gym/?student_id=${this.props.user.id}${topics}`)
      .then(({data}) => {
        const qa = data
          .map(q => ({
            question: q.fields.question,
            answers: [
              q.fields.option1,
              q.fields.option2,
              q.fields.option3,
              q.fields.option4,
            ],
            xblock_id: q.pk,
            correct: ([
              q.fields.option1_iscorrect,
              q.fields.option2_iscorrect,
              q.fields.option3_iscorrect,
              q.fields.option4_iscorrect,
            ]).findIndex(x => x)
          }));
        console.log('qa', qa);
        this.setState({qa});
        let temp_data = [];
        for (let i = 0; i < qa.length; ++i) {
          temp_data.push(i);
        }
        this.setState({activeQuestion: 0, data: temp_data});
        this.props.loadTestQuestions(qa);
        this.props.loadTestAnswers(qa.map(elem => elem.correct));
        // setTimeout(() => this.props.history.push('/test/ongoingTest'), 4000);
      })
      .catch(e => {
        console.log(e);
        console.log(e.response);
      })
  };
  submitCurrentQuestion = cb => {
    const {id} = this.props.user;
    console.log(this.props.test, this.state.activeQuestion, this.props.user);
    const payload = {
      student_id: id,
      xblock_id: this.props.test.qa[this.state.activeQuestion].xblock_id,
      attempted: this.props.test.answers[this.state.activeQuestion] !== -1 ? 1 : 0,
      correctly_attempted: this.props.test.answers[this.state.activeQuestion] === this.props.test.qa[this.state.activeQuestion].correct ? 1 : 0,
      time_taken: 10.0,
      timestamp: this.getTimeInFormat(new Date()),
      appeared_in_test: 1,
      appeared_in_gym: 0,
    };

    if (this.props.test.answers[this.state.activeQuestion] === -1) {
      
      this.setState({skipped: this.state.skipped + 1})
    }
    else if (this.props.test.answers[this.state.activeQuestion] === this.props.test.qa[this.state.activeQuestion].correct) {
      this.setState({correct: this.state.correct + 1})
    }
    else {
      this.setState({incorrect: this.state.incorrect + 1})
    }

    let data = new FormData();
    data.append("student_id", id);
    data.append("xblock_id", this.props.test.qa[this.state.activeQuestion].xblock_id);
    data.append("attempted", this.props.test.answers[this.state.activeQuestion] !== -1 ? 1 : 0);
    data.append("correctly_attempted", this.props.test.answers[this.state.activeQuestion] === this.props.test.qa[this.state.activeQuestion].correct ? 1 : 0);
    data.append("time_taken", 10.0);
    data.append("timestamp", this.getTimeInFormat(new Date()));
    data.append("appeared_in_test", 0);
    data.append("appeared_in_gym", 1);

    console.log(payload, data);

    var xhr = new XMLHttpRequest();
    xhr.withCredentials = true;

    xhr.addEventListener("readystatechange", function () {
      if (this.readyState === 4) {
        console.log(this.responseText);
        cb();
      }
    });

    xhr.open("POST", "http://api.classcast.in/classcast/submission/newsubmission");
    xhr.setRequestHeader("Cache-Control", "no-cache");

    xhr.send(data);
  };
  getTimeInFormat = now => {
    const year = now.getYear() + 1900;
    const month = now.getMonth() + 1 > 9 ? now.getMonth() + 1 : '0' + (now.getMonth() + 1);
    const day = now.getDate() > 9 ? now.getDate() : '0' + now.getDate();

    const hours = now.getHours() > 9 ? now.getHours() : '0' + now.getHours();
    const mins = now.getMinutes() > 9 ? now.getMinutes() : '0' + now.getMinutes();
    const secs = now.getSeconds() > 9 ? now.getSeconds() : '0' + now.getSeconds();

    return `${year}-${month}-${day} ${hours}:${mins}:${secs}`;
  };
  nextQuestion = () => {
    if (this.state.activeQuestion === this.state.data.length - 1) {
      this.loadNewQuestions();
      this._carousel.snapToItem(0);
    }
    else {
      this.submitCurrentQuestion(() => {
        this._carousel.snapToNext();
      });
    }
  };
  _showConfirmationPopup = () => {
    this.setState({showSubmitConfirm: true})
  };
  _renderItem = ({item, index}) => {
    return (
      <View style={styles.navigatorItem}>
        <Text style={styles.navigatorItemText}>
          {index + 1}
        </Text>
      </View>
    );
  }

  constructor() {
    super();
    this.state = {
      activeQuestion: 0,
      data: [],
      showSubmitConfirm: false,
      correct: 0,
      skipped: 0,
      incorrect: 0,
    }
  }

  componentDidMount() {
    this.loadNewQuestions();
  }

  render() {
    if (!this.props.test.qa.length) {
      return <View/>;
    }
    return (
      <View style={styles.container}>
        <NavigationBar
          test={true}
          challenge={true}
          rightButtonAction={() => this._showConfirmationPopup()}
          rightButtonStyle={'REVIEW_CLOSE'}
        />
        <View style={styles.ongoingTest}>
          <View style={[styles.questionNavigator, {height: 0}]}>
            <TouchableNativeFeedback
              onPress={() => {
                this._carousel.snapToPrev()
              }}
            >
              <View style={styles.navigatorPrevious}>
                <Image
                  style={{height: '75%', width: '100%'}}
                  resizeMode={'contain'}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </View>
            </TouchableNativeFeedback>
            <View style={{marginLeft: 0.125 * screen.width}}>
              <SnapCarousel
                ref={(c) => this._carousel = c}
                data={this.state.data}
                renderItem={this._renderItem.bind(this)}
                sliderWidth={0.75 * screen.width}
                itemWidth={0.15 * screen.width}
                enableMomentum={true}
                inactiveSlideScale={0.66}
                inactiveSlideOpacity={0.5}
                autoplayDelay={100}
                autoplayInterval={1000}
                onSnapToItem={index => {
                  this.submitCurrentQuestion(() => {
                    this.setState({activeQuestion: index});
                    this.props.goToQues(index);
                  });
                }}
              />
            </View>
            <TouchableNativeFeedback
              onPress={() => {
                this._carousel.snapToNext()
              }}
            >
              <View style={styles.navigatorNext}>
                <Image
                  style={{height: '75%', width: '100%'}}
                  resizeMode={'contain'}
                  source={{uri: 'data:image/png;base64,'}}
                />
              </View>
            </TouchableNativeFeedback>
          </View>
          <QAPanel/>
          <View style={styles.nextQuestionWrapper}>
            <TouchableNativeFeedback
              onPress={() => this.nextQuestion()}
            >
              <View style={styles.nextQuestion}>
                <Image
                  style={{
                    position: 'absolute',
                    top: 0,
                    height: '100%',
                    width: '100%',
                  }}
                  resizeMode={'contain'}
                  source={{uri: 'data:image/png;base64,'}}
                />
                <Text style={styles.nextQuestionText}>
                  NEXT
                </Text>
              </View>
            </TouchableNativeFeedback>
          </View>
        </View>
        {
          this.state.showSubmitConfirm &&
          <View style={styles.submitConfirmOverlay}>
            <Image
              style={styles.gymSubmitBG}
              source={{uri: 'data:image/png;base64,'}}
            />
            <View style={styles.conceptGymStatsContainer}>
              <View style={styles.conceptStats}>
                <Text style={styles.conceptStatsNumber}>{this.state.correct}</Text>
                <Text style={styles.conceptStatsLabel}>Correct</Text>
              </View>
              <View style={styles.conceptStats}>
                <Text style={styles.conceptStatsNumber}>{this.state.skipped}</Text>
                <Text style={styles.conceptStatsLabel}>Skipped</Text>
              </View>
              <View style={styles.conceptStats}>
                <Text style={styles.conceptStatsNumber}>{this.state.incorrect}</Text>
                <Text style={styles.conceptStatsLabel}>Incorrect</Text>
              </View>
            </View>
            <View style={[styles.submitConfirmContainer, styles.conceptPopupPatch]}>
              <View style={styles.messageTextContainer}>
                <Text style={styles.messageText}>Are you sure you want to exit?</Text>
              </View>
              <View style={styles.submitConfirmButtonsContainer}>
                <TouchableNativeFeedback
                  onPress={() => {
                    this.props.history.push('/')
                    firebaseApp.analytics().logEvent('Exited_Gym', {Incorrect: this.state.incorrect, Correct: this.state.correct, Skipped: this.state.skipped  });
                  }}
                >
                  <View style={styles.submitConfirmButton}>
                    <Text style={styles.submitConfirmButtonText}>Yes</Text>
                  </View>
                </TouchableNativeFeedback>
                <TouchableNativeFeedback
                  onPress={() => this.setState({showSubmitConfirm: false})}
                >
                  <View style={[styles.submitConfirmButton, {backgroundColor: '#a268cc'}]}>
                    <Text style={[styles.submitConfirmButtonText, {color: 'white'}]}>No</Text>
                  </View>
                </TouchableNativeFeedback>
              </View>
            </View>
          </View>
        }
      </View>
    )
  }
}

const mapStateToProps = state => ({
  gym: state.concept,
  user: state.user,
  test: state.test,
});
const mapDispatchToProps = dispatch => bindActionCreators({
  goToQues: goToQuestion,
  loadCarousel: loadCarousel,
  loadTestQuestions: loadTestQuestions,
  loadTestAnswers: loadTestAnswers,
}, dispatch);

export default connect(mapStateToProps, mapDispatchToProps)(OngoingGym);